package com.hbm.machine.turret.greg;
import api.hbm.redstoneoverradio.IRORInteractive;
import com.hbm.api.computer.*;
import com.hbm.bomb.nuclear.LegacyVector;
import com.hbm.machine.turret.*;
import com.hbm.multiblock.DummyableBlock;
import com.hbm.registry.HbmSounds;
import com.hbm.weapon.artillery.*;
import com.hbm.weapon.sedna.BulletConfig;
import com.hbm.weapon.sedna.gun.legendary.CasingEffects;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.network.PacketDistributor;
/** True three-mode TileEntityTurretArty: high/low ballistic solutions,real shell/cargo dispatch,source queue/recoil/delayed huge casing. */
public final class GregTurretEntity extends ArtilleryTurretBase {
 public static final short MODE_ARTILLERY=0,MODE_CANNON=1,MODE_MANUAL=2;public final GregTurretKind kind;public short mode;private boolean didJustShoot,retracting;public double barrelPos,lastBarrelPos;private int timer;
 public GregTurretEntity(GregTurretKind kind,BlockPos pos,BlockState state){super(GregTurretContent.entity(kind),pos,state);this.kind=kind;}
 @Override public boolean isValidBlockState(BlockState state){return getType().isValid(state)&&DummyableBlock.isCore(state);}@Override protected String title(){return "container.turretArty";}@Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new GregTurretMenu(kind,id,inventory,this,worldPosition);}
 @Override protected List<BulletConfig> ammoConfigs(){return List.of();}@Override public List<ItemStack> displayedAmmo(){return ArtilleryAmmoItem.creative();}@Override public long getMaxPower(){return 100000;}@Override public double barrelLength(){return 9;}@Override public double acceptableInaccuracy(){return 0;}@Override public double heightOffset(){return 3;}@Override public double detectorRange(){return mode==MODE_CANNON?250:3000;}@Override public double detectorGrace(){return mode==MODE_CANNON?32:250;}@Override public double yawSpeed(){return 1;}@Override public double pitchSpeed(){return .5;}@Override public double depression(){return 30;}@Override public double elevation(){return 90;}@Override public int detectorInterval(){return mode==MODE_CANNON?20:200;}@Override protected boolean doLOSCheck(){return mode==MODE_CANNON;}public double velocity(){return mode==MODE_CANNON?20:50;}
 @Override public Vec3 horizontalOffset(){return switch(getBlockState().getValue(DummyableBlock.LEGACY_META)-10){case 2->new Vec3(1,0,1);case 4->new Vec3(1,0,0);case 5->new Vec3(0,0,1);default->Vec3.ZERO;};}
 @Override public void turnTowards(Vec3 target){var p=turretPosition();var barrel=muzzleOffset();p=p.add(barrel.xCoord,barrel.yCoord,barrel.zCoord);var delta=target.subtract(p);double targetYaw=-Math.atan2(delta.x,delta.z),x=Math.sqrt(delta.x*delta.x+delta.z*delta.z),y=delta.y,v=velocity(),v2=v*v,g=9.81*.05,upperLower=mode==MODE_CANNON?-1:1;double targetPitch=Math.atan((v2+Math.sqrt(v2*v2-g*(g*x*x+2*y*v2))*upperLower)/(g*x));turnTowardsAngle(targetPitch,targetYaw);}
 public ItemStack shellLoaded(){for(int slot=1;slot<10;slot++)if(slots.get(slot).is(ArtilleryAmmoContent.AMMO.get()))return slots.get(slot);return ItemStack.EMPTY;}
 private void consumeShell(){for(int slot=1;slot<10;slot++)if(slots.get(slot).is(ArtilleryAmmoContent.AMMO.get())){removeItem(slot,1);return;}setChanged();}
 private void spawnShell(ItemStack stack){var p=turretPosition();var vec=muzzleOffset();var projectile=new ArtilleryShellEntity(level).shellType(ArtilleryAmmoItem.metadata(stack));projectile.moveTo(p.x+vec.xCoord,p.y+vec.yCoord,p.z+vec.zCoord,0,0);projectile.setThrowableHeading(vec.xCoord,vec.yCoord,vec.zCoord,(float)velocity(),0);projectile.setTarget((int)tPos.x,(int)tPos.y,(int)tPos.z);if(ArtilleryAmmoItem.metadata(stack)==ArtyShellTypes.CARGO&&ArtilleryAmmoItem.hasCargo(stack))projectile.setCargo(ArtilleryAmmoItem.cargo(stack,level.registryAccess()));projectile.shouldWhistle=mode!=MODE_CANNON;level.addFreshEntity(projectile);casingDelay=7;}
 @Override public void tickServer(ServerLevel server){connect(server);if(mode==MODE_MANUAL){if(!targetQueue.isEmpty())tPos=targetQueue.getFirst();}else targetQueue.clear();aligned=false;if(target!=null&&!target.isAlive()){target=null;stattrak++;}if(target!=null&&mode!=MODE_MANUAL&&!entityInLOS(target))target=null;if(target!=null)tPos=entityPosition(target);else if(mode!=MODE_MANUAL)tPos=null;if(active()&&hasPower()){if(tPos!=null)turnTowards(tPos);}else{target=null;tPos=null;}if(!active())targetQueue.clear();if(target!=null&&!target.isAlive()){target=null;tPos=null;stattrak++;}if(active()&&hasPower()){searchTimer--;setPower(getPower()-consumption());if(searchTimer<=0){searchTimer=detectorInterval();if(target==null&&mode!=MODE_MANUAL)seekNewTarget();}}else searchTimer=0;if(aligned)updateFiringTick();chargeBattery();sync(250);didJustShoot=false;if(casingDelay>0)casingDelay--;else spawnCasing();}
 @Override public void tickClient(){lastBarrelPos=barrelPos;if(retracting){barrelPos+=.5;if(barrelPos>=1)retracting=false;}else{barrelPos-=.05;if(barrelPos<0)barrelPos=0;}super.tickClient();}
 @Override protected void updateFiringTick(){timer++;int delay=mode==MODE_ARTILLERY?300:40;if(timer%delay!=0)return;var shell=shellLoaded();if(!shell.isEmpty()){cachedCasing=ArtyShellTypes.casing(ArtilleryAmmoItem.metadata(shell));spawnShell(shell);consumeShell();level.playSound(null,worldPosition.getX(),worldPosition.getY(),worldPosition.getZ(),HbmSounds.get("turret.jeremy_fire"),SoundSource.BLOCKS,25,1);didJustShoot=true;if(level instanceof ServerLevel server){var p=turretPosition();var vec=muzzleOffset();var tag=new CompoundTag();tag.putString("type","smoke");tag.putFloat("size",0);tag.putByte("count",(byte)5);var packet=new TurretEffects.Packet(p.x+vec.xCoord,p.y+vec.yCoord,p.z+vec.zCoord,tag);for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<=22500)PacketDistributor.sendToPlayer(player,packet);}}if(mode==MODE_MANUAL&&!targetQueue.isEmpty()){targetQueue.removeFirst();tPos=null;}}
 @Override protected void spawnCasing(){if(cachedCasing==null)return;var p=turretPosition();CasingEffects.composeEffect(level,p.x,p.y,p.z,(float)Math.toDegrees(rotationYaw),(float)-Math.toDegrees(rotationPitch),-.6,.3,0,.01,level.random.nextFloat()*20-10,0,cachedCasing.getName(),true,200,1,20);cachedCasing=null;}
 @Override public void control(int button){if(button==5){mode++;if(mode>2)mode=0;tPos=null;targetQueue.clear();setChanged();}else super.control(button);}
 @Override protected void saveMachine(CompoundTag tag){super.saveMachine(tag);tag.putShort("mode",mode);}@Override protected void loadMachine(CompoundTag tag){super.loadMachine(tag);mode=tag.getShort("mode");}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=super.getUpdateTag(lookup);tag.putBoolean("hbm_arty_shot",didJustShoot);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){super.handleUpdateTag(tag,lookup);retracting=tag.getBoolean("hbm_arty_shot");}
 @Override public String[] computerMethods(){return new String[]{"setActive","isActive","getEnergyInfo","getWhitelisted","addWhitelist","removeWhitelist","setTargeting","getTargeting","hasTarget","getAngle","isAligned","getCurrentTarget","getTargetDistance","addCoords"};}
 @Override public Object[] callComputer(String method,ComputerArguments args){if(method.equals("addCoords")){mode=MODE_MANUAL;double x=args.checkDouble(0),y=args.checkDouble(1),z=args.checkDouble(2),dx=worldPosition.getX()-x,dy=worldPosition.getY()-y,dz=worldPosition.getZ()-z;if(Math.sqrt(dx*dx+dy*dy+dz*dz)>=detectorRange())return new Object[]{false};targetQueue.add(new Vec3(x,y,z));setChanged();return new Object[]{true};}return super.callComputer(method,args);}
 @Override public String[] getFunctionInfo(){return new String[]{PREFIX_FUNCTION+"setactive"+NAME_SEPARATOR+"active (0 or 1)",PREFIX_FUNCTION+"targetplayers"+NAME_SEPARATOR+"enabled (0 or 1)",PREFIX_FUNCTION+"targetanimals"+NAME_SEPARATOR+"enabled (0 or 1)",PREFIX_FUNCTION+"targetmobs"+NAME_SEPARATOR+"enabled (0 or 1)",PREFIX_FUNCTION+"targetmachines"+NAME_SEPARATOR+"enabled (0 or 1)",PREFIX_FUNCTION+"addwhitelist"+NAME_SEPARATOR+"name",PREFIX_FUNCTION+"removewhitelist"+NAME_SEPARATOR+"name",PREFIX_FUNCTION+"setmode"+NAME_SEPARATOR+"mode",PREFIX_FUNCTION+"enqueue"+NAME_SEPARATOR+"x"+PARAM_SEPARATOR+"y"+PARAM_SEPARATOR+"z"};}
 @Override public String runRORFunction(String name,String[] args){super.runRORFunction(name,args);if((PREFIX_FUNCTION+"setmode").equals(name)&&args.length==1){mode=(short)IRORInteractive.parseInt(args[0],0,2);setChanged();}return null;}
}
